insert into public.animal_entries(id,species_id,slug,entry_kind,common_names,scientific_name,origin,activity,beginner_suitability,size_text,lifespan_text,image_url,image_alt,content,citation_ids,review_status,publication_status,reviewed_at,sort_order) values ('c0579e2d-8fa5-5f9b-a21b-4ac3061445aa','478e1712-6945-5a0e-a7a9-9e5ce1ab9627','shiba-inu','breed','{"en-US":"Shiba Inu","en-GB":"Shiba Inu","vi":"Shiba Inu"}'::jsonb,'Canis lupus familiaris','Japan','high','experienced-care',null,null,'/brand/pawtome-logo.png','{"en-US":"Shiba Inu catalog entry","en-GB":"Shiba Inu catalog entry","vi":"Shiba Inu, mục trong danh mục"}'::jsonb,'{"summary":{"en-US":"A recognized dog breed. Breed tendencies never guarantee an individual dog''s behavior or health.","en-GB":"A recognized dog breed. Breed tendencies never guarantee an individual dog''s behavior or health.","vi":"Một giống chó được công nhận. Xu hướng giống không bao giờ bảo đảm hành vi hay sức khỏe của từng chó."},"housing":{"en-US":"Provide safe rest, toileting access, exercise, and space matched to the individual.","en-GB":"Provide safe rest, toileting access, exercise, and space matched to the individual.","vi":"Cần nơi nghỉ an toàn, cơ hội đi vệ sinh, vận động và không gian phù hợp từng cá thể."},"feeding":{"en-US":"Feed a complete diet appropriate to life stage and body condition; individual plans belong with a veterinarian.","en-GB":"Feed a complete diet appropriate to life stage and body condition; individual plans belong with a veterinarian.","vi":"Cho ăn khẩu phần hoàn chỉnh phù hợp giai đoạn sống và thể trạng; kế hoạch cá nhân cần bác sĩ thú y."},"enrichment":{"en-US":"Use sniffing, play, exploration, and reward-based learning.","en-GB":"Use sniffing, play, exploration, and reward-based learning.","vi":"Dùng đánh hơi, chơi, khám phá và học có thưởng."},"socialNeeds":{"en-US":"Provide safe voluntary interaction and protected rest; social preference varies.","en-GB":"Provide safe voluntary interaction and protected rest; social preference varies.","vi":"Tạo tương tác an toàn, tự nguyện và thời gian nghỉ; sở thích xã hội khác nhau."},"maintenance":{"en-US":"Coat, nail, dental, ear, and preventive care need entry-specific review.","en-GB":"Coat, nail, dental, ear, and preventive care need entry-specific review.","vi":"Lông, móng, răng, tai và chăm sóc phòng ngừa cần rà soát riêng."},"training":{"en-US":"Use reward-based methods and short sessions.","en-GB":"Use reward-based methods and short sessions.","vi":"Dùng phương pháp có thưởng và buổi tập ngắn."},"welfare":{"en-US":"Assess exercise, care cost, conformation concerns, and the individual—not appearance alone.","en-GB":"Assess exercise, care cost, conformation concerns, and the individual—not appearance alone.","vi":"Cân nhắc vận động, chi phí, hình thể và từng cá thể—không chỉ ngoại hình."},"health":{"en-US":"Entry-specific predispositions need review; this catalog does not diagnose or predict health.","en-GB":"Entry-specific predispositions need review; this catalog does not diagnose or predict health.","vi":"Khuynh hướng riêng cần rà soát; danh mục không chẩn đoán hay dự đoán sức khỏe."},"suitability":{"en-US":"Children and other pets require adult supervision, gradual introductions, and individual assessment.","en-GB":"Children and other pets require adult supervision, gradual introductions, and individual assessment.","vi":"Trẻ em và thú khác cần người lớn giám sát, làm quen từ từ và đánh giá từng cá thể."},"climateSensitivity":{"en-US":"Tolerance varies with coat, body shape, age, and health; seek entry-specific advice.","en-GB":"Tolerance varies with coat, body shape, age, and health; seek entry-specific advice.","vi":"Khả năng chịu khí hậu tùy lông, hình thể, tuổi và sức khỏe; cần tư vấn riêng."}}'::jsonb,array['fci-breed-nomenclature','wsava-nutrition','avsab-humane-training','aaha-behavior-guidelines']::text[],'needs-entry-review','published','2026-08-14',0) on conflict (slug) do update set species_id=excluded.species_id,entry_kind=excluded.entry_kind,common_names=excluded.common_names,scientific_name=excluded.scientific_name,origin=excluded.origin,activity=excluded.activity,beginner_suitability=excluded.beginner_suitability,size_text=excluded.size_text,lifespan_text=excluded.lifespan_text,image_url=excluded.image_url,image_alt=excluded.image_alt,content=excluded.content,citation_ids=excluded.citation_ids,review_status=excluded.review_status,publication_status=excluded.publication_status,reviewed_at=excluded.reviewed_at,sort_order=excluded.sort_order;
