 resources.","vi":"Cho quyền lựa chọn, làm quen từ từ và đủ tài nguyên tách biệt."},"maintenance":{"en-US":"Coat, claw, dental, and preventive care need entry-specific review.","en-GB":"Coat, claw, dental, and preventive care need entry-specific review.","vi":"Lông, móng, răng và chăm sóc phòng ngừa cần rà soát riêng."},"training":{"en-US":"Use reward-based cooperative care and environmental setup without force.","en-GB":"Use reward-based cooperative care and environmental setup without force.","vi":"Dùng chăm sóc hợp tác có thưởng và sắp xếp môi trường, không ép buộc."},"welfare":{"en-US":"Select for health and welfare, not appearance alone.","en-GB":"Select for health and welfare, not appearance alone.","vi":"Ưu tiên sức khỏe và phúc lợi, không chỉ ngoại hình."},"health":{"en-US":"Entry-specific predispositions need review; changes need veterinary assessment.","en-GB":"Entry-specific predispositions need review; changes need veterinary assessment.","vi":"Khuynh hướng riêng cần rà soát; thay đổi cần bác sĩ thú y đánh giá."},"suitability":{"en-US":"Use calm supervised interaction and gradual introductions; suitability is individual.","en-GB":"Use calm supervised interaction and gradual introductions; suitability is individual.","vi":"Tương tác bình tĩnh có giám sát và làm quen từ từ; phù hợp tùy cá thể."},"climateSensitivity":{"en-US":"Tolerance varies with coat, skin, body shape, age, and health.","en-GB":"Tolerance varies with coat, skin, body shape, age, and health.","vi":"Khả năng chịu khí hậu tùy lông, da, hình thể, tuổi và sức khỏe."}}'::jsonb,array['cfa-recognized-breeds','wsava-nutrition','aaha-behavior-guidelines']::text[],'needs-entry-review','published','2026-08-14',34) on conflict (slug) do update set species_id=excluded.species_id,entry_kind=excluded.entry_kind,common_names=excluded.common_names,scientific_name=excluded.scientific_name,origin=excluded.origin,activity=excluded.activity,beginner_suitability=excluded.beginner_suitability,size_text=excluded