insert into public.animal_entries(id,species_id,slug,entry_kind,common_names,scientific_name,origin,activity,beginner_suitability,size_text,lifespan_text,image_url,image_alt,content,citation_ids,review_status,publication_status,reviewed_at,sort_order) values ('2f670e35-709c-5b71-8ea9-b643b59602f7','47e3fc05-e702-5329-b489-2b601202d81d','society-finch','species','{"en-US":"Society Finch","en-GB":"Society Finch","vi":"Sẻ xã hội"}'::jsonb,'Lonchura striata domestica','Captive variety','high','needs-review',null,null,'/brand/pawtome-logo.png','{"en-US":"Society Finch catalog entry","en-GB":"Society Finch catalog entry","vi":"Sẻ xã hội, mục trong danh mục"}'::jsonb,'{"summary":{"en-US":"A companion-bird species or variety with complex species-specific welfare needs.","en-GB":"A companion-bird species or variety with complex species-specific welfare needs.","vi":"Một loài hoặc biến thể chim cảnh có nhu cầu phúc lợi phức tạp theo loài."},"housing":{"en-US":"Provide a clean secure enclosure and safe exercise or flight space.","en-GB":"Provide a clean secure enclosure and safe exercise or flight space.","vi":"Cung cấp chuồng sạch, an toàn và không gian bay hoặc vận động."},"feeding":{"en-US":"Diet is species-specific; seed-only diets are not complete guidance.","en-GB":"Diet is species-specific; seed-only diets are not complete guidance.","vi":"Khẩu phần tùy loài; chế độ chỉ ăn hạt không phải hướng dẫn hoàn chỉnh."},"enrichment":{"en-US":"Provide foraging, manipulation, bathing or preening, exercise, and rest.","en-GB":"Provide foraging, manipulation, bathing or preening, exercise, and rest.","vi":"Tạo cơ hội tìm thức ăn, thao tác, tắm hay rỉa lông, vận động và nghỉ."},"socialNeeds":{"en-US":"Social and privacy needs vary; avoid both isolation and forced interaction.","en-GB":"Social and privacy needs vary; avoid both isolation and forced interaction.","vi":"Nhu cầu xã hội và riêng tư khác nhau; tránh cô lập lẫn ép tương tác."},"maintenance":{"en-US":"Daily cleaning and observation are general needs; details require avian review.","en-GB":"Daily cleaning and observation are general needs; details require avian review.","vi":"Vệ sinh và quan sát hằng ngày là nhu cầu chung; chi tiết cần chuyên gia chim."},"training":{"en-US":"Use voluntary reward-based handling for cooperative care.","en-GB":"Use voluntary reward-based handling for cooperative care.","vi":"Dùng xử lý tự nguyện có thưởng cho chăm sóc hợp tác."},"welfare":{"en-US":"Small cages, poor diet, sleep disruption, and inadequate enrichment compromise welfare.","en-GB":"Small cages, poor diet, sleep disruption, and inadequate enrichment compromise welfare.","vi":"Chuồng nhỏ, khẩu phần kém, gián đoạn ngủ và thiếu làm giàu môi trường ảnh hưởng phúc lợi."},"health":{"en-US":"No species-specific diagnosis is asserted; subtle changes need prompt avian-veterinary advice.","en-GB":"No species-specific diagnosis is asserted; subtle changes need prompt avian-veterinary advice.","vi":"Không chẩn đoán riêng theo loài; thay đổi kín đáo cần tư vấn thú y chim sớm."},"suitability":{"en-US":"Adult responsibility is essential; birds can be fragile, stressed, and capable of biting.","en-GB":"Adult responsibility is essential; birds can be fragile, stressed, and capable of biting.","vi":"Người lớn phải chịu trách nhiệm; chim có thể mong manh, căng thẳng và cắn."},"climateSensitivity":{"en-US":"Temperature, humidity, drafts, ventilation, and light cycles need species review.","en-GB":"Temperature, humidity, drafts, ventilation, and light cycles need species review.","vi":"Nhiệt độ, độ ẩm, gió lùa, thông gió và chu kỳ sáng cần rà soát theo loài."}}'::jsonb,array['aav-basic-care','aav-environmental-needs']::text[],'needs-entry-review','published','2026-08-14',46) on conflict (slug) do update set species_id=excluded.species_id,entry_kind=excluded.entry_kind,common_names=excluded.common_names,scientific_name=excluded.scientific_name,origin=excluded.origin,activity=excluded.activity,beginner_suitability=ex