panions while others are solitary or territorial.","vi":"Có loài cần bạn phù hợp, có loài sống đơn hoặc bảo vệ lãnh thổ."},"maintenance":{"en-US":"Daily observation and cleaning are general; details need species review.","en-GB":"Daily observation and cleaning are general; details need species review.","vi":"Quan sát và vệ sinh hằng ngày là nhu cầu chung; chi tiết cần rà soát theo loài."},"training":{"en-US":"Use calm reward-based handling; never force a fearful animal.","en-GB":"Use calm reward-based handling; never force a fearful animal.","vi":"Xử lý bình tĩnh có thưởng; không ép con vật đang sợ."},"welfare":{"en-US":"Insufficient space, wrong companionship, poor diet, and unsuitable handling are welfare risks.","en-GB":"Insufficient space, wrong companionship, poor diet, and unsuitable handling are welfare risks.","vi":"Thiếu không gian, bầu bạn sai, khẩu phần kém và xử lý không phù hợp là nguy cơ."},"health":{"en-US":"Entry-specific risks need review; small mammals may hide illness.","en-GB":"Entry-specific risks need review; small mammals may hide illness.","vi":"Nguy cơ riêng cần rà soát; thú nhỏ có thể che giấu bệnh."},"suitability":{"en-US":"An adult must provide care; many are fragile, nocturnal, or stressed by handling.","en-GB":"An adult must provide care; many are fragile, nocturnal, or stressed by handling.","vi":"Người lớn phải chăm sóc; nhiều loài mong manh, hoạt động đêm hoặc căng thẳng khi bế."},"climateSensitivity":{"en-US":"Temperature, humidity, ventilation, bedding, and heat exposure need species review.","en-GB":"Temperature, humidity, ventilation, bedding, and heat exposure need species review.","vi":"Nhiệt độ, độ ẩm, thông gió, chất lót và phơi nóng cần rà soát theo loài."}}'::jsonb,array['rspca-small-pets','merck-rabbit-home']::text[],'needs-entry-review','published','2026-08-14',54) on conflict (slug) do update set species_id=excluded.species_id,entry_kind=excluded.entry_kind,common_names=excluded.common_names,scientific_name=excluded.scie