lly.","vi":"Nhiều bò sát khỏe nhất khi nuôi riêng; không trộn loài và phải rà soát nuôi chung."},"maintenance":{"en-US":"Measure heat and humidity, maintain hygiene, and keep husbandry records.","en-GB":"Measure heat and humidity, maintain hygiene, and keep husbandry records.","vi":"Đo nhiệt và độ ẩm, giữ vệ sinh và ghi chép chăm sóc."},"training":{"en-US":"Keep habituation and handling voluntary and species-appropriate.","en-GB":"Keep habituation and handling voluntary and species-appropriate.","vi":"Làm quen và xử lý tự nguyện, phù hợp loài."},"welfare":{"en-US":"Incorrect heat, UV, humidity, diet, space, or social housing can cause serious harm.","en-GB":"Incorrect heat, UV, humidity, diet, space, or social housing can cause serious harm.","vi":"Nhiệt, UV, độ ẩm, khẩu phần, không gian hay nuôi chung sai có thể gây hại nghiêm trọng."},"health":{"en-US":"No diagnosis is asserted; abnormal appetite, shedding, breathing, or posture needs an exotics veterinarian.","en-GB":"No diagnosis is asserted; abnormal appetite, shedding, breathing, or posture needs an exotics veterinarian.","vi":"Không chẩn đoán; ăn uống, lột da, hô hấp hay tư thế bất thường cần bác sĩ thú y ngoại lai."},"suitability":{"en-US":"Adult care, secure separation from other pets, and hygiene are essential.","en-GB":"Adult care, secure separation from other pets, and hygiene are essential.","vi":"Người lớn chăm sóc, tách an toàn khỏi thú khác và vệ sinh là thiết yếu."},"climateSensitivity":{"en-US":"Controlled species-specific environmental ranges are required; room temperature is not a care plan.","en-GB":"Controlled species-specific environmental ranges are required; room temperature is not a care plan.","vi":"Cần môi trường kiểm soát theo loài; nhiệt độ phòng không phải kế hoạch chăm sóc."}}'::jsonb,array['merck-reptile-husbandry']::text[],'needs-entry-review','published','2026-08-14',55) on conflict (slug) do update set species_id=excluded.species_id,entry_kind=excluded.entry_kind,common_names=excluded.common_names,scientific_name=excluded.scientific_name,origin=excluded.origin,activity=excluded.activity,beginner_suitability=excluded.beginner_suitability,size_text=excluded.size_text,lifespan_text=excluded.lifespan_text,image_url=excluded.image_url,image_alt=excluded.image_alt,content=excluded.content,citation_ids=excluded.citation_ids,review_status=excluded.review_status,publication_status=excluded.publication_status,reviewed_at=excluded.reviewed_at,sort_order=excluded.sort_order;
