insert into public.animal_entries(id,species_id,slug,entry_kind,common_names,scientific_name,origin,activity,beginner_suitability,size_text,lifespan_text,image_url,image_alt,content,citation_ids,review_status,publication_status,reviewed_at,sort_order) values ('0d72399a-f520-58ce-ac3a-78da1be6805e','84253ee2-d800-5dba-b6e7-1bfeebedc556','siamese-fighting-fish','variety','{"en-US":"Siamese Fighting Fish","en-GB":"Siamese Fighting Fish","vi":"Cá betta"}'::jsonb,'Betta splendens','Southeast Asia','moderate','experienced-care',null,null,'/brand/pawtome-logo.png','{"en-US":"Siamese Fighting Fish catalog entry","en-GB":"Siamese Fighting Fish catalog entry","vi":"Cá betta, mục trong danh mục"}'::jsonb,'{"summary":{"en-US":"A freshwater species whose welfare depends on compatible water, stocking, social, and habitat conditions.","en-GB":"A freshwater species whose welfare depends on compatible water, stocking, social, and habitat conditions.","vi":"Một loài cá nước ngọt có phúc lợi phụ thuộc nước, mật độ, xã hội và môi trường phù hợp."},"housing":{"en-US":"Cycle the aquarium and match volume, filtration, temperature, chemistry, cover, and flow to the species.","en-GB":"Cycle the aquarium and match volume, filtration, temperature, chemistry, cover, and flow to the species.","vi":"Hoàn thiện chu trình bể và phù hợp thể tích, lọc, nhiệt, hóa học nước, nắp và dòng theo loài."},"feeding":{"en-US":"Feed an appropriate complete diet without compromising water quality.","en-GB":"Feed an appropriate complete diet without compromising water quality.","vi":"Cho ăn khẩu phần hoàn chỉnh phù hợp mà không làm xấu nước."},"enrichment":{"en-US":"Provide species-appropriate plants, shelter, swimming space, substrate, and grouping.","en-GB":"Provide species-appropriate plants, shelter, swimming space, substrate, and grouping.","vi":"Cung cấp cây, chỗ trú, vùng bơi, nền và nhóm phù hợp loài."},"socialNeeds":{"en-US":"Schooling, territorial, solitary, and sex-ratio needs differ.","en-GB":"Schooling, territorial, solitary, and sex-ratio needs differ.","vi":"Nhu cầu đàn, lãnh thổ, sống đơn và tỷ lệ giới tính khác nhau."},"maintenance":{"en-US":"Test water, maintain filtration, and make regular partial changes without abrupt shifts.","en-GB":"Test water, maintain filtration, and make regular partial changes without abrupt shifts.","vi":"Kiểm tra nước, duy trì lọc và thay một phần đều đặn, tránh thay đổi đột ngột."},"training":{"en-US":"Focus on low-stress observation and husbandry rather than training claims.","en-GB":"Focus on low-stress observation and husbandry rather than training claims.","vi":"Tập trung quan sát ít căng thẳng và chăm sóc thay vì khẳng định huấn luyện."},"welfare":{"en-US":"Poor water, overcrowding, incompatible stocking, and uncycled systems are preventable risks.","en-GB":"Poor water, overcrowding, incompatible stocking, and uncycled systems are preventable risks.","vi":"Nước kém, quá đông, ghép cá sai và bể chưa ổn định là nguy cơ phòng tránh được."},"health":{"en-US":"Signs are nonspecific; test the environment and consult an aquatic veterinarian before treatment.","en-GB":"Signs are nonspecific; test the environment and consult an aquatic veterinarian before treatment.","vi":"Dấu hiệu không đặc hiệu; kiểm tra môi trường và hỏi bác sĩ thú y thủy sinh trước điều trị."},"suitability":{"en-US":"An adult must manage water testing, equipment, feeding, and veterinary decisions.","en-GB":"An adult must manage water testing, equipment, feeding, and veterinary decisions.","vi":"Người lớn phải quản lý kiểm tra nước, thiết bị, cho ăn và quyết định thú y."},"climateSensitivity":{"en-US":"Control aquarium temperature and chemistry for the species, not ambient weather.","en-GB":"Control aquarium temperature and chemistry for the species, not ambient weather.","vi":"Kiểm soát nhiệt độ và hóa học nước theo loài, không theo thời tiết phòng."}}'::jsonb,array['merck-fish-home']::text[],'needs-entry-review','published','2026-08-14',63) on conflict (slug) do update set species_id=excluded.species_id,entry_kind=excluded.entry_kind,common_names=excluded.common_names,scientific_name=excluded.scientific_name,origin=excluded.origin,activity=excluded.activity,beginner_suitability=excluded.beginner_suitability,size_text=excluded.size_text,lifespan_text=excluded.lifespan_text,image_url=excluded.image_url,image_alt=excluded.image_alt,content=excluded.content,citation_ids=excluded.citation_ids,review_status=excluded.review_status,publication_status=excluded.publication_status,reviewed_at=excluded.reviewed_at,sort_order=excluded.sort_order;
